'use strict';
let guestCredentials=null,guestSessionPromise=null,guestActive=false,guestBackupBusy=false,guestBackupTimer=null,guestBackupConflict=false,guestRestoring=false;
let guestBackupRaw=null;
let guestBackupDirty=false,guestBackupUrgent=false,guestBackupStatus='checking';
try{const value=JSON.parse(localStorage.getItem('kanji_guest_credentials_v1')||'null');if(/^[a-f0-9]{64}$/.test(value?.token||'')&&/^[a-f0-9]{32}$/.test(value?.guestId||''))guestCredentials=value;}catch{}
function guestHeaders(){return guestCredentials?{'X-Kanji-Guest':guestCredentials.token,...(guestCredentials.useGuest?{'X-Kanji-Guest-Mode':'1'}:{})}:{};}
function rememberGuest(value){guestCredentials=value;try{localStorage.setItem('kanji_guest_credentials_v1',JSON.stringify(value));}catch{guestNote('ゲストIDを端末に保存できません。画面を閉じる前に復元コードを控えてください。');}}
async function guestRequest(path,method='GET',body,options={}){
 const controller=typeof AbortController==='function'?new AbortController():null,timer=controller&&!options.signal?setTimeout(()=>controller.abort(),20000):null;
 try{
  const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{...(typeof playerDeviceId!=='undefined'?{'X-Kanji-Device':playerDeviceId}:{}),...guestHeaders(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),...(controller?{signal:controller.signal}:{}),...options});
  let value;try{value=await response.json();}catch{throw Object.assign(Error(response.status===413?'保存データが送信上限を超えています。端末バックアップを保存してください。':response.status===429?'サーバーが混み合っています。少し待って再試行してください。':'サーバーの応答を確認できません（HTTP '+response.status+'）。時間をおいて再試行してください。'),{status:response.status});}
  if(!response.ok)throw Object.assign(Error(value.error||'接続できません（HTTP '+response.status+'）。'),{status:response.status,code:value.code,retryAfter:Math.max(0,Number(response.headers.get('Retry-After'))||0)*1000});return value;
 }catch(error){if(error.name==='AbortError')throw Error('サーバーへの通信が時間切れになりました。接続を確認して再試行してください。');throw error;}
 finally{if(timer!==null)clearTimeout(timer);}
}
function guestNote(text){const el=document.getElementById('guest-player-status');if(el)el.textContent=text;}
async function ensureGuestSession(){if(guestRestoring)throw Error('ゲスト情報を復元中です。少しお待ちください。');if(guestSessionPromise)return guestSessionPromise;guestSessionPromise=(async()=>{let session=await guestRequest('/api/session');if(!session.guest){if(guestCredentials&&!session.authenticated)throw Error('保存したゲストIDを確認できません。復元コードから再接続してください。');rememberGuest({...await guestRequest('/api/guest','POST',{}),useGuest:true});session={authenticated:true,guest:true};}guestActive=!!session.guest;if(guestActive)guestBackupStatus=guestCredentials?.revision>0?'saved':'waiting';if(guestActive&&guestCredentials&&!guestCredentials.useGuest)rememberGuest({...guestCredentials,useGuest:true});renderGuestPlayer();return session;})();try{return await guestSessionPromise;}catch(error){guestSessionPromise=null;guestNote(error.message);throw error;}}
function guestSaveStatus(){return guestBackupConflict||saveRecoveryBlocked?'blocked':guestBackupBusy?'saving':guestBackupStatus==='failed'?'failed':guestBackupDirty?'waiting':guestBackupStatus;}
function renderGuestPlayer(){const panel=document.getElementById('guest-player-panel');if(!panel)return;const indicator=document.getElementById('guest-save-state');if(indicator){const status=guestSaveStatus();indicator.textContent={checking:'保存を確認中',waiting:'保存待ち',saving:'保存中',saved:'保存済み',failed:'保存失敗・再試行待ち',blocked:'保存待ち・確認が必要'}[status]||'保存待ち';indicator.dataset.status=status;const badge=document.getElementById('guest-save-badge');if(badge){badge.textContent=indicator.textContent;badge.dataset.status=status;}}document.getElementById('guest-code-details').hidden=!guestActive;const help=document.getElementById('guest-account-help');if(help)help.hidden=guestActive;const code=document.getElementById('guest-recovery-code');code.value=guestActive?guestCredentials?.recoveryCode||'':'';const time=document.getElementById('guest-backup-time');if(time)time.textContent=guestCredentials?.savedAt?'最後のサーバー保存：'+new Date(guestCredentials.savedAt).toLocaleString('ja-JP'):guestCredentials?.revision>0?'サーバーに保存済み（日時は未確認）':'まだサーバーに保存されていません';const backup=document.getElementById('btn-guest-backup');if(backup){backup.disabled=guestBackupBusy;backup.textContent=guestSaveStatus()==='blocked'?'保存内容の確認が必要（再確認）':guestBackupBusy?'サーバーに保存しています…':'今のデータをサーバーに保存';}}
window.openGuestRecoveryCode=async()=>{try{await ensureGuestSession();const panel=document.getElementById('guest-player-panel');panel.open=true;panel.querySelector('.guest-code-view').open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('guest-recovery-code').focus({preventScroll:true});}catch(error){guestNote(error.message);document.getElementById('guest-player-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}};
window.copyGuestRecoveryCode=async()=>{try{await ensureGuestSession();if(!guestActive||!guestCredentials?.recoveryCode)return;await navigator.clipboard.writeText(guestCredentials.recoveryCode);guestNote('復元コードをコピーしました。他の人には公開しないでください。');}catch{document.getElementById('guest-recovery-code').select();guestNote('復元コードを選択しました。長押ししてコピーしてください。');}};
async function guestSnapshotHash(raw){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw))),n=>n.toString(16).padStart(2,'0')).join('');}
function scheduleGuestBackup(delay){if(guestBackupTimer!==null)clearTimeout(guestBackupTimer);guestBackupTimer=setTimeout(()=>{guestBackupTimer=null;backupGuestNow().catch(error=>{guestBackupDirty=true;guestBackupStatus='failed';guestNote(error.message);renderGuestPlayer();});},delay);}
let guestBackupTask=null;
const performGuestBackup=async(options={})=>{
 if(options.manual&&saveRecoveryBlocked&&typeof saveStore!=='undefined'&&saveStore&&!saveStore.blocked&&typeof validSave==='function'&&validSave(gameState)){try{saveStore.write(gameState);saveRecoveryBlocked=false;}catch{}}
 await ensureGuestSession();if(!guestActive||guestRestoring)return;if(saveRecoveryBlocked||guestBackupConflict&&!options.manual){guestBackupStatus='blocked';guestNote(saveRecoveryBlocked&&typeof saveFailureMessage!=='undefined'&&saveFailureMessage?saveFailureMessage:'保存データを保護するため、サーバーへの上書きを停止しています。「保存が止まった理由を確認」を押してください。');renderGuestPlayer();return;}if(guestBackupBusy){guestBackupDirty=true;guestBackupUrgent=true;return;}if(guestBackupTimer!==null)clearTimeout(guestBackupTimer);guestBackupTimer=null;guestBackupBusy=true;guestBackupDirty=false;guestBackupUrgent=false;guestBackupStatus='saving';renderGuestPlayer();let failed=false,sentRaw=null;
 try{if(options.manual){const latest=await guestRequest('/api/guest/state');
  if(latest.revision!==guestCredentials.revision){const raw=JSON.stringify(latest.state),hash=await guestSnapshotHash(raw);if(raw!==JSON.stringify(gameState)&&hash!==guestCredentials.backupHash)throw Object.assign(Error('サーバーと端末の保存内容が異なります。端末バックアップを保存し、保存・復元から確認してください。'),{status:409});}
  rememberGuest({...guestCredentials,revision:latest.revision});guestBackupConflict=false;}const raw=JSON.stringify(gameState),hash=await guestSnapshotHash(raw);guestBackupRaw=raw;if(!options.manual&&hash===guestCredentials.backupHash){guestBackupStatus='saved';guestNote('最新のデータはサーバーに保存済みです。');return;}const payload={state:JSON.parse(raw),revision:guestCredentials.revision||0},keepalive=!!options.leaving&&new TextEncoder().encode(JSON.stringify(payload)).length<60000;sentRaw=raw;const result=await guestRequest('/api/guest/state','PUT',payload,keepalive?{keepalive:true}:{});rememberGuest({...guestCredentials,revision:result.revision,savedAt:result.savedAt,backupHash:hash});guestBackupRaw=raw;guestBackupStatus='saved';guestNote('サーバーに保存しました。');}
 catch(error){
  // A committed PUT can lose its reply. Confirm exact bytes before retrying.
  if(sentRaw){try{const latest=await guestRequest('/api/guest/state');if(JSON.stringify(latest.state)===sentRaw){rememberGuest({...guestCredentials,revision:latest.revision,savedAt:latest.savedAt,backupHash:await guestSnapshotHash(sentRaw)});guestBackupRaw=sentRaw;guestBackupDirty=JSON.stringify(gameState)!==sentRaw;guestBackupStatus='saved';guestBackupConflict=false;guestNote('サーバーへの保存完了を再確認しました。');return;}}catch{}}
  failed=true;guestBackupDirty=true;guestBackupStatus='failed';if(error.status===409)guestBackupConflict=true;guestNote('サーバーへの保存待ち：'+error.message+' 端末のバックアップ保存もご利用ください。');}
 finally{guestBackupBusy=false;renderGuestPlayer();if(guestBackupDirty&&!guestBackupConflict&&!guestRestoring&&!saveRecoveryBlocked)scheduleGuestBackup(failed?30000:0);}
};
window.backupGuestNow=async(options={})=>{
 if(guestBackupTask){if(!options.manual){guestBackupDirty=true;guestBackupUrgent=true;return;}await guestBackupTask;if(guestBackupTask)return window.backupGuestNow(options);}
 const pending=performGuestBackup(options);guestBackupTask=pending;try{return await pending;}finally{if(guestBackupTask===pending)guestBackupTask=null;}
};
window.queueGuestBackup=(urgent=false)=>{if(guestBackupRaw!==null&&JSON.stringify(gameState)===guestBackupRaw&&!guestBackupDirty)return;guestBackupDirty=true;if(urgent===true)guestBackupUrgent=true;if(!guestActive||guestRestoring||guestBackupConflict)return;if(guestBackupBusy){guestBackupUrgent=true;return;}guestBackupStatus='waiting';renderGuestPlayer();if(guestBackupUrgent)scheduleGuestBackup(0);else if(guestBackupTimer===null)scheduleGuestBackup(15000);};
function flushGuestBackup(){if(guestActive&&!guestRestoring&&!guestBackupConflict){backupGuestNow({leaving:true}).catch(error=>guestNote(error.message));}}
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden)flushGuestBackup();});
window.addEventListener('pagehide',flushGuestBackup);
window.addEventListener('online',()=>queueGuestBackup(true));
window.restoreGuestPlayer=async()=>{if(guestRestoring)return;if(typeof friendRoom!=='undefined'&&friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching||typeof soloBattlePending!=='undefined'&&!soloBattlePending&&!isBattleEnded&&document.getElementById('screen-battle')?.classList.contains('hidden')===false){guestNote('対局やマッチングを終了してから復元してください。');return;}const recoveryCode=document.getElementById('guest-restore-code').value.trim();if(!recoveryCode){guestNote('復元コードを入力してください。');return;}const button=document.getElementById('btn-guest-restore');button.disabled=true;button.textContent='復元データを確認しています…';guestNote('復元データを確認しています…');guestRestoring=true;clearTimeout(guestBackupTimer);guestBackupTimer=null;try{if(guestBackupBusy)throw Error('バックアップの完了を待ってから復元してください。');const result=await guestRequest('/api/guest/restore','POST',{recoveryCode});if(result.state){const migrated=migrateCatalogueSave(result.state);if(!validSave(migrated))throw Error('サーバーのバックアップを読み込めませんでした。端末のデータは変更していません。');if(!saveStore)throw Error('復元データを端末に保存できません。');saveStore.replace(migrated);saveRecoveryBlocked=true;}rememberGuest({...result,state:undefined,useGuest:true});guestActive=true;guestBackupConflict=false;guestSessionPromise=null;if(!result.state){guestNote('対人RP・フレンド情報を復元しました。所持文字等のサーバーバックアップはまだありません。必要なら端末のバックアップを読み込んでください。');setTimeout(()=>location.reload(),2000);}else location.reload();}catch(error){guestNote(error.message);}finally{button.disabled=false;button.textContent='このコードのデータを復元';guestRestoring=false;}};
window.addEventListener('load',()=>{ensureGuestSession().then(()=>{if(guestActive)queueGuestBackup();}).catch(error=>guestNote(error.message));});

window.loadGuestBackups=async()=>{const list=document.getElementById('guest-backup-list');list.textContent='読み込み中…';try{await ensureGuestSession();const result=await guestRequest('/api/guest/backups');list.replaceChildren();if(!result.backups.length){list.textContent='過去のバックアップはまだありません。次の保存から順に残ります。';return;}for(const entry of result.backups){const row=document.createElement('div'),text=document.createElement('p'),button=document.createElement('button');row.className='guest-history-entry';text.textContent=new Date(entry.savedAt).toLocaleString('ja-JP')+'／'+entry.coins.toLocaleString()+'文・段位ポイント '+entry.rating.toLocaleString()+'・所持 '+entry.owned+'体';button.type='button';button.className='inventory-action secondary';button.textContent='この保存時点に戻す';button.onclick=()=>restoreGuestBackup(entry.revision,button);row.append(text,button);list.append(row);}}catch(error){list.textContent=error.message;}};
window.restoreGuestBackup=async(revision,button)=>{if(guestRestoring||guestBackupBusy)return;if(typeof friendRoom!=='undefined'&&friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching||typeof soloBattlePending!=='undefined'&&!soloBattlePending&&!isBattleEnded){guestNote('対局やマッチングを終了してから戻してください。');return;}button.disabled=true;try{const result=await guestRequest('/api/guest/backups/'+revision),migrated=migrateCatalogueSave(result.state);if(!validSave(migrated)||!saveStore)throw Error('バックアップを読み込めません。現在のデータは変更していません。');await backupGuestNow({manual:true});if(guestBackupStatus!=='saved'||guestBackupDirty||saveRecoveryBlocked)throw Error('現在のデータを保存できなかったため、復元を中止しました。');guestRestoring=true;if(guestBackupTimer!==null)clearTimeout(guestBackupTimer);guestBackupTimer=null;saveStore.replace(migrated);saveRecoveryBlocked=true;rememberGuest({...guestCredentials,backupHash:undefined});location.reload();}catch(error){guestNote(error.message);guestRestoring=false;button.disabled=false;}};

// Read-only diagnosis: never clears a protection flag or replaces either save.
window.inspectGuestSave=async()=>{
 const button=document.getElementById('btn-guest-diagnose'),note=document.getElementById('guest-save-diagnosis');button.disabled=true;document.getElementById('btn-guest-repair-login').hidden=true;note.textContent='端末とサーバーの保存状態を確認しています…';
 try{
  await ensureGuestSession();const latest=await guestRequest('/api/guest/state');
  const summary=state=>state?`${Number(state.coins).toLocaleString('ja-JP')}文・所持${state.inventory?.length||0}体・段位ポイント${state.rating}`:'保存なし';
  const lines=[`この端末：${summary(gameState)}`,`サーバー：${summary(latest.state)}`];
  if(saveRecoveryBlocked)lines.push('端末保存の保護が働いています。バックアップ保存と端末の自動バックアップを確認してください。');
  else if(latest.state&&(latest.state.loginBonusOrdinal||0)>(gameState.loginBonusOrdinal||0)){document.getElementById('btn-guest-repair-login').hidden=false;lines.push('ログイン報酬の受取記録が異なります。ログインボーナスの「受取状況を再確認」で確認してください。一致しない場合は端末バックアップを保存してから「端末の進行を維持して保存を修復」を選べます。');}
  else if(guestBackupConflict)lines.push('サーバーとの保存内容に差があり、上書きを停止しています。端末バックアップを保存してから、復元する保存内容を確認してください。');
  else lines.push('今のデータをサーバーに保存して再試行できます。');
  note.textContent=lines.join(' ／ ');
 }catch(error){note.textContent='確認できませんでした：'+error.message;}finally{button.disabled=false;}
};

window.repairGuestLoginSave=async()=>{
 const button=document.getElementById('btn-guest-repair-login');if(guestRestoring||guestBackupBusy||saveRecoveryBlocked)return;
 if(typeof friendRoom!=='undefined'&&friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching||document.getElementById('screen-battle')?.classList.contains('hidden')===false||window.isGachaPresentationBusy?.()){guestNote('対局・召喚・マッチングを終了してから修復してください。');return;}
 button.disabled=true;let original=null,overlay=null,attempted=false;
 try{
  await ensureGuestSession();const latest=await guestRequest('/api/guest/state'),bonus=await guestRequest('/api/login-bonus');
  original=JSON.stringify(gameState);const local=JSON.parse(original),ordinal=bonus.ordinal;
  if(!validSave(local)||!saveStore||saveStore.blocked)throw Error('端末の保存を保護しています。バックアップを確認してください。');
  if(ordinal<=(local.loginBonusOrdinal||0)||(latest.state?.loginBonusOrdinal||0)!==ordinal)throw Error('受取状況が変わりました。「保存が止まった理由を確認」から再確認してください。');
  const summary=s=>`${s.coins.toLocaleString('ja-JP')}文・所持${s.inventory.length}体・段位ポイント${s.rating}`;
  if(!confirm('端末バックアップをファイルに保存してから実行してください。\n\n維持する端末データ：'+summary(local)+'\n置き換えるサーバーデータ：'+summary(latest.state)+'\n\n端末の文・かけら・文字・育成・編成・段位を維持し、受取記録だけを合わせます。受取済み報酬は追加しません。旧サーバー保存はバックアップに残します。\nこの内容で修復しますか？'))return;
  if(JSON.stringify(gameState)!==original)throw Error('端末の状態が変わりました。もう一度確認してください。');
  saveStore.write(local);guestRestoring=true;clearTimeout(guestBackupTimer);guestBackupTimer=null;
  overlay=document.createElement('div');overlay.className='editor-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','保存の修復中');overlay.innerHTML='<section class="editor-panel"><p role="status">端末の進行を維持して保存を修復しています…</p></section>';document.body.append(overlay);overlay.tabIndex=-1;overlay.addEventListener('keydown',event=>{if(event.key==='Tab'||event.key==='Escape'){event.preventDefault();event.stopPropagation();}});overlay.focus({preventScroll:true});pausePlayerOverlay();
  const payload={state:local,revision:latest.revision,ordinal,confirmPreserveDevice:true};attempted=true;
  let result;try{result=await guestRequest('/api/guest/reconcile-login','POST',payload);}catch(error){const check=await guestRequest('/api/guest/state'),expected={...local,loginBonusOrdinal:ordinal};if(JSON.stringify(check.state)!==JSON.stringify(expected))throw error;result=check;}
  const expected={...local,loginBonusOrdinal:ordinal};if(JSON.stringify(gameState)!==original||JSON.stringify(result.state)!==JSON.stringify(expected))throw Error('保存中に状態が変わりました。再確認してください。');
  saveStore.write(expected);gameState=expected;rememberGuest({...guestCredentials,revision:result.revision,savedAt:result.savedAt,backupHash:await guestSnapshotHash(JSON.stringify(expected))});guestBackupRaw=JSON.stringify(expected);guestBackupDirty=false;guestBackupConflict=false;guestBackupStatus='saved';button.hidden=true;
  guestNote('端末の進行を維持して保存を修復しました。受取済み報酬は追加していません。');document.getElementById('guest-save-diagnosis').textContent='修復完了：'+summary(expected)+'。ログインボーナスの受取状況を再確認できます。';
 }catch(error){if(attempted)guestBackupConflict=true;guestNote('修復を完了できませんでした：'+error.message+' 端末データは初期化していません。');}
 finally{guestRestoring=false;button.disabled=false;if(overlay){overlay.remove();resumePlayerEngine();(button.hidden?document.getElementById('btn-guest-diagnose'):button).focus({preventScroll:true});}renderGuestPlayer();}
};
